import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { apiAddUser } from "../service/user";
import { useNotice } from "../context/NoticeContext";

const Overlay = styled.div`
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex; justify-content: center; align-items: center;
  z-index: 999;
`;

const Popup = styled.div`
  background: white;
  padding: 30px;
  border-radius: 10px;
  width: 500px;
  position: relative;
  max-height: 80vh;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px; right: 10px;
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
`;

const Title = styled.h2`
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 30px;
  text-align: center;
`;

const InputGroup = styled.div`
  margin-bottom: 15px;
  width: 100%;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 5px;
  font-weight: bold;
`;

const Input = styled.input`
  width: 100%;
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const PasswordWrapper = styled.div`
  position: relative;
`;

const EyeIcon = styled.span`
  position: absolute;
  right: 0px; top: 50%;
  transform: translateY(-50%);
  cursor: pointer;
  font-size: 18px;
`;

const Button = styled.button`
  padding: 10px 15px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  width: 100%;
  margin-top: 20px;
`;

const ErrorMsg = styled.div`
  color: red;
  font-size: 13px;
`;

const AddUserPopup = ({ onClose }) => {
  const { t } = useTranslation();
  const { showNotice } = useNotice();
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    phone: "",
    username: "",
    address: "",
    birthday: "",
    gender: "",
    career: "",
    workplace: "",
  });

  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);

  const validate = () => {
    const errs = {};
    if (!formData.email.includes("@")) errs.email = t("addUserComponent.errorEmail");
    if (formData.password.length < 6) errs.password = t("addUserComponent.errorPassword");
    if (!formData.username) errs.username = t("addUserComponent.errorUsername");
    if (!formData.phone.match(/^[0-9]{9,11}$/)) errs.phone = t("addUserComponent.errorPhone");
    if (!formData.birthday) errs.birthday = t("addUserComponent.errorBirthday");
    return errs;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async () => {
    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    try {
      await apiAddUser(formData);
      showNotice(t("addUserComponent.addUserSuccess"));
      onClose();
    } catch (err) {
      showNotice(t("addUserComponent.addUserFail"));
    }
  };

  return (
    <Overlay>
      <Popup>
        <CloseButton onClick={onClose}>×</CloseButton>
        <Title>{t("addUserComponent.title")}</Title>
        <InputGroup>
        <Label>{t("addUserComponent.email")}</Label>
        <Input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
        />
        {errors.email && <ErrorMsg>{errors.email}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.username")}</Label>
        <Input
            type="text"
            name="username"
            value={formData.username}
            onChange={handleChange}
        />
        {errors.username && <ErrorMsg>{errors.username}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.phone")}</Label>
        <Input
            type="text"
            name="phone"
            value={formData.phone}
            onChange={handleChange}
        />
        {errors.phone && <ErrorMsg>{errors.phone}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.address")}</Label>
        <Input
            type="text"
            name="address"
            value={formData.address}
            onChange={handleChange}
        />
        {errors.address && <ErrorMsg>{errors.address}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.birthday")}</Label>
        <Input
            type="date"
            name="birthday"
            value={formData.birthday}
            onChange={handleChange}
        />
        {errors.birthday && <ErrorMsg>{errors.birthday}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.gender")}</Label>
        <div>
            <label>
            <Input
                type="radio"
                name="gender"
                value="male"
                checked={formData.gender === "male"}
                onChange={handleChange}
            />
            {t("addUserComponent.male")}
            </label>
            <label>
            <Input
                type="radio"
                name="gender"
                value="female"
                checked={formData.gender === "female"}
                onChange={handleChange}
            />
            {t("addUserComponent.female")}
            </label>
        </div>
        {errors.gender && <ErrorMsg>{errors.gender}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.career")}</Label>
        <Input
            type="text"
            name="career"
            value={formData.career}
            onChange={handleChange}
        />
        {errors.career && <ErrorMsg>{errors.career}</ErrorMsg>}
        </InputGroup>

        <InputGroup>
        <Label>{t("addUserComponent.workplace")}</Label>
        <Input
            type="text"
            name="workplace"
            value={formData.workplace}
            onChange={handleChange}
        />
        {errors.workplace && <ErrorMsg>{errors.workplace}</ErrorMsg>}
        </InputGroup>



        <Button onClick={handleSubmit}>{t("addUserComponent.confirm")}</Button>
      </Popup>
    </Overlay>
  );
};

export default AddUserPopup;
